let () =
  match
    Vhs.tape
      ~settings:
        [
          Shell Bash;
          Font_size 18;
          Width 1000;
          Height 460;
          Theme "Builtin Dark";
          Padding 20;
          Typing_speed (Ms 20);
        ]
      ~outputs:[ "examples/layout/layout.gif" ]
      [
        Vhs.raw
          "# Generated by tape.ml: permanent history above bounded current \
           activity.";
        Vhs.raw {|Require "dune"|};
        Vhs.type' "dune exec examples/layout/main.exe\n";
        (* VHS does not match the final line once the live rows have been
           redrawn, so wait out the six-second run instead. *)
        Vhs.sleep (Ms 10000);
      ]
  with
  | Ok t -> print_string (Vhs.to_string t)
  | Error e ->
      prerr_endline e;
      exit 1
